func cacheBestBeaconStateOnErrFn(highestSlot primitives.Slot, key [32]byte) customProcessingFn {
	return func(ctx context.Context, state state.BeaconState) error {
		if ctx.Err() != nil {
			// Cache last best value.
			if highestSlot < state.Slot() {
